//! Independently re-execute the native linked meta-theory corpus in Rust.
//! The program, cases and coverage are generated by
//! scripts/generate-meta-theory-native.mjs from the preserved upstream tokens;
//! this mirror re-runs every recorded case and every ablation witness on the
//! Rust reducer and rejects corrupted programs, preludes, cases and witnesses.
use rml::meta_theory_native::{
    ablation_outcome, binary_natural, compact_native, execute_native, expand_native, native_closure,
    native_registry, natural_value, render_native_value, slice_native_program, META_THEORY_NATIVE_PROGRAM,
};
use rml::Node;
use serde_json::Value;
use sha2::{Digest, Sha256};
use std::collections::{BTreeMap, BTreeSet};

const PRELUDE: &str = include_str!("../../lib/meta-theory/meta-theory-native-prelude.lino");
const PROGRAM: &str = include_str!("../../lib/meta-theory/upstream-0.0.3-native.lino");
const CASES: &str = include_str!("../../test-corpus/meta-theory-native/cases.json");
const COVERAGE: &str = include_str!("../../test-corpus/meta-theory-native/coverage.json");

fn on_large_stack<F: FnOnce() + Send + 'static>(run: F) {
    std::thread::Builder::new()
        .stack_size(256 * 1024 * 1024)
        .spawn(run)
        .unwrap()
        .join()
        .unwrap();
}

fn sha256(text: &str) -> String {
    Sha256::digest(text.as_bytes())
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect()
}

fn node(value: &Value) -> Node {
    match value {
        Value::String(text) => Node::Leaf(text.clone()),
        Value::Array(children) => Node::List(children.iter().map(node).collect()),
        _ => panic!("fixture terms must contain strings and arrays only"),
    }
}

fn leaf(text: &str) -> Node {
    Node::Leaf(text.to_string())
}

fn strings(value: &Value) -> Vec<String> {
    value
        .as_array()
        .map(|items| items.iter().map(|item| item.as_str().unwrap().to_string()).collect())
        .unwrap_or_default()
}

/// Recorded and structural references of every declaration.
fn references(declarations: &[Value]) -> BTreeMap<String, Vec<String>> {
    declarations
        .iter()
        .map(|entry| {
            let mut all = strings(&entry["references"]);
            all.extend(strings(&entry["structuralReferences"]));
            (entry["address"].as_str().unwrap().to_string(), all)
        })
        .collect()
}

/// Naturals, lists, pairs, options and Booleans only (the shared rendering subset).
fn plain_data(value: &Value) -> bool {
    const TAGS: &[&str] = &[
        "mt-v", "mt-natural", "mt-zero", "mt-nil", "mt-cons", "mt-pair", "mt-some", "mt-none", "mt-true", "mt-false",
    ];
    match value {
        Value::String(text) => TAGS.contains(&text.as_str()) || text.chars().all(|character| character.is_ascii_digit()),
        Value::Array(items) => items.iter().all(plain_data),
        _ => false,
    }
}

struct Scope {
    reexecute_cases: bool,
    addresses: Option<Vec<String>>,
}

fn validate(prelude: &str, program: &str, cases: &Value, coverage: &Value, scope: &Scope) -> Vec<String> {
    let mut problems = Vec::new();
    let program_hash = sha256(program);
    if cases["programHash"].as_str() != Some(program_hash.as_str())
        || coverage["programHash"].as_str() != Some(program_hash.as_str())
    {
        problems.push("program hash differs from the recorded evidence".to_string());
    }
    let prelude_hash = sha256(prelude);
    if cases["preludeHash"].as_str() != Some(prelude_hash.as_str())
        || coverage["preludeHash"].as_str() != Some(prelude_hash.as_str())
    {
        problems.push("prelude hash differs from the recorded evidence".to_string());
    }
    let whole = match native_registry(prelude, program) {
        Ok(registry) => registry,
        Err(error) => {
            problems.push(format!("native program does not load: {error}"));
            return problems;
        }
    };
    let items = cases["cases"].as_array().unwrap();
    let by_id: BTreeMap<&str, &Value> = items
        .iter()
        .map(|item| (item["id"].as_str().unwrap(), item))
        .collect();
    if scope.reexecute_cases {
        for item in items {
            let outcome = execute_native(&whole, &expand_native(&node(&item["request"])));
            let reproduced = outcome.term.as_ref().is_some_and(|term| {
                compact_native(term) == node(&item["expected"])
                    && outcome.steps as u64 == item["steps"].as_u64().unwrap()
                    && outcome.value() == item["value"].as_bool().unwrap()
            });
            if !reproduced {
                problems.push(format!(
                    "{}: re-execution differs from the recorded normal form",
                    item["id"].as_str().unwrap()
                ));
            }
        }
    }
    let declarations = coverage["declarations"].as_array().unwrap();
    let graph = references(declarations);
    for entry in declarations {
        let address = entry["address"].as_str().unwrap();
        let witness = &entry["executionWitness"];
        if witness.is_null()
            || scope
                .addresses
                .as_ref()
                .is_some_and(|only| !only.iter().any(|item| item == address))
        {
            continue;
        }
        if entry["status"].as_str() != Some("elaborated") {
            problems.push(format!("{address}: witness claimed for an unelaborated declaration"));
            continue;
        }
        let case_id = witness["case"].as_str().unwrap_or("");
        let Some(item) = by_id.get(case_id) else {
            problems.push(format!("{address}: witness case {case_id} is missing"));
            continue;
        };
        if item["value"].as_bool() != Some(true) {
            problems.push(format!("{address}: witness case {case_id} does not reach a value"));
            continue;
        }
        let recorded = strings(&item["closure"]);
        if !recorded.iter().any(|member| member == address) {
            problems.push(format!("{address}: witness case does not reach the declaration"));
            continue;
        }
        let recorded_set: BTreeSet<String> = recorded.iter().cloned().collect();
        if native_closure(&graph, &recorded) != recorded_set {
            problems.push(format!("{address}: witness closure is not closed under recorded references"));
            continue;
        }
        let expected = node(&item["expected"]);
        let request = expand_native(&node(&item["request"]));
        let local = native_registry(prelude, &slice_native_program(program, &recorded))
            .map(|local| execute_native(&local, &request));
        if !local.as_ref().is_ok_and(|outcome| ablation_outcome(&expected, outcome) == "unchanged") {
            problems.push(format!("{address}: witness case does not reach its value on its static closure"));
            continue;
        }
        let without: Vec<String> = recorded.into_iter().filter(|member| member != address).collect();
        let outcome = native_registry(prelude, &slice_native_program(program, &without))
            .map(|ablated| ablation_outcome(&expected, &execute_native(&ablated, &request)))
            .unwrap_or("failure");
        let claimed = witness["ablation"].as_str().unwrap_or("");
        let claimed_class = if claimed.starts_with("failure") { "failure" } else { claimed };
        if outcome == "unchanged" {
            problems.push(format!("{address}: removing its rules leaves {case_id} unchanged"));
        } else if outcome != claimed_class {
            problems.push(format!("{address}: ablation outcome {outcome} differs from {claimed}"));
        }
    }
    problems
}

fn fixtures() -> (Value, Value) {
    (serde_json::from_str(CASES).unwrap(), serde_json::from_str(COVERAGE).unwrap())
}

#[test]
fn reexecutes_every_case_and_ablation_witness() {
    on_large_stack(|| {
        let (cases, coverage) = fixtures();
        assert_eq!(coverage["declarationCount"], 229);
        assert_eq!(coverage["elaborated"], 229);
        assert_eq!(coverage["exactDependencies"], 229);
        assert_eq!(coverage["commandCount"], 197);
        assert_eq!(coverage["evaluationsExecuted"], 90);
        assert_eq!(coverage["executionWitnessed"], 150);
        let witnessed = coverage["declarations"]
            .as_array()
            .unwrap()
            .iter()
            .filter(|entry| !entry["executionWitness"].is_null())
            .count();
        assert_eq!(witnessed, 150);
        let executions = cases["cases"]
            .as_array()
            .unwrap()
            .iter()
            .filter(|item| item["kind"] == "command-execution")
            .collect::<Vec<_>>();
        assert_eq!(executions.len(), 90);
        assert!(executions.iter().all(|item| item["value"] == true));
        let scope = Scope { reexecute_cases: true, addresses: None };
        assert_eq!(validate(PRELUDE, PROGRAM, &cases, &coverage, &scope), Vec::<String>::new());
    });
}

#[test]
fn renders_values_like_the_shared_fixtures() {
    on_large_stack(|| {
        let (cases, _) = fixtures();
        let registry = native_registry(PRELUDE, PROGRAM).unwrap();
        for item in cases["cases"].as_array().unwrap() {
            let Some(rendered) = item["rendered"].as_str() else { continue };
            if !plain_data(&item["expected"]) {
                continue;
            }
            let outcome = execute_native(&registry, &expand_native(&node(&item["request"])));
            let language = item["language"].as_str().unwrap_or("lean");
            assert_eq!(render_native_value(outcome.term.as_ref().unwrap(), language), rendered, "{}", item["id"]);
        }
    });
}

#[test]
fn rejects_a_corrupted_definition_body() {
    on_large_stack(|| {
        let (cases, coverage) = fixtures();
        let start = PROGRAM.find("# rml.formal.lean.NetworkExamples.").unwrap();
        let corrupted = format!(
            "{}{}",
            &PROGRAM[..start],
            PROGRAM[start..].replacen("(mt-add ", "(mt-mul ", 1)
        );
        assert_ne!(corrupted, PROGRAM);
        let scope = Scope { reexecute_cases: true, addresses: Some(Vec::new()) };
        let problems = validate(PRELUDE, &corrupted, &cases, &coverage, &scope);
        assert!(problems.contains(&"program hash differs from the recorded evidence".to_string()));
        assert!(problems.iter().any(|problem| problem.contains("re-execution differs")), "{problems:?}");
    });
}

#[test]
fn rejects_corrupted_prelude_semantics() {
    on_large_stack(|| {
        let (cases, coverage) = fixtures();
        let corrupted = PRELUDE.replacen("(to (mt-v (mt-b1 ?n))))", "(to (mt-v (mt-b0 ?n))))", 1);
        assert_ne!(corrupted, PRELUDE);
        let scope = Scope { reexecute_cases: true, addresses: Some(Vec::new()) };
        let problems = validate(&corrupted, PROGRAM, &cases, &coverage, &scope);
        assert!(problems.contains(&"prelude hash differs from the recorded evidence".to_string()));
        assert!(problems.iter().any(|problem| problem.contains("re-execution differs")));
    });
}

fn with_witness(coverage: &Value, address: &str, witness: Value) -> Value {
    let mut forged = coverage.clone();
    for entry in forged["declarations"].as_array_mut().unwrap() {
        if entry["address"] == address {
            entry["executionWitness"] = witness.clone();
        }
    }
    forged
}

#[test]
fn rejects_forged_unreachable_and_relabelled_witnesses() {
    on_large_stack(|| {
        let (cases, coverage) = fixtures();
        let only = |address: &str| Scope { reexecute_cases: false, addresses: Some(vec![address.to_string()]) };
        let items = cases["cases"].as_array().unwrap();
        let passive = "rml.formal.lean.NetworkDefinitions.TupleOfReferencesDefault";
        let reaching = items
            .iter()
            .find(|item| item["value"] == true && strings(&item["closure"]).iter().any(|member| member == passive))
            .unwrap();
        let reaching_id = reaching["id"].as_str().unwrap();
        let forged = with_witness(&coverage, passive, serde_json::json!({ "case": reaching_id, "ablation": "stuck" }));
        assert_eq!(
            validate(PRELUDE, PROGRAM, &cases, &forged, &only(passive)),
            vec![format!("{passive}: removing its rules leaves {reaching_id} unchanged")]
        );

        let isolated = "rml.formal.lean.SequenceDefinitions.listGetD";
        let other = items
            .iter()
            .find(|item| item["value"] == true && !strings(&item["closure"]).iter().any(|member| member == isolated))
            .unwrap();
        let unreachable = with_witness(&coverage, isolated, serde_json::json!({ "case": other["id"], "ablation": "stuck" }));
        assert_eq!(
            validate(PRELUDE, PROGRAM, &cases, &unreachable, &only(isolated)),
            vec![format!("{isolated}: witness case does not reach the declaration")]
        );

        let witnessed = coverage["declarations"]
            .as_array()
            .unwrap()
            .iter()
            .find(|entry| !entry["executionWitness"].is_null())
            .unwrap();
        let address = witnessed["address"].as_str().unwrap();
        let mut relabelled_witness = witnessed["executionWitness"].clone();
        relabelled_witness["ablation"] = Value::String("different-value".to_string());
        let relabelled = with_witness(&coverage, address, relabelled_witness);
        let problems = validate(PRELUDE, PROGRAM, &cases, &relabelled, &only(address));
        assert!(problems.iter().any(|problem| problem.contains("ablation outcome stuck differs")), "{problems:?}");

        let missing = with_witness(&coverage, address, serde_json::json!({ "case": "no-such-case", "ablation": "stuck" }));
        let problems = validate(PRELUDE, PROGRAM, &cases, &missing, &only(address));
        assert!(problems.iter().any(|problem| problem.contains("is missing")));
    });
}

#[test]
fn rejects_edited_results_and_step_counts() {
    on_large_stack(|| {
        let (mut cases, coverage) = fixtures();
        let items = cases["cases"].as_array_mut().unwrap();
        for item in items.iter_mut() {
            if item["id"] == "rml.formal.rocq.NetworkExamples#command-40-execution" {
                item["expected"] = serde_json::json!(["mt-v", ["mt-natural", "13"]]);
            }
        }
        let closed = items.iter_mut().find(|item| item["kind"] == "closed-normalization").unwrap();
        closed["steps"] = Value::from(closed["steps"].as_u64().unwrap() + 1);
        let scope = Scope { reexecute_cases: true, addresses: Some(Vec::new()) };
        let problems = validate(PRELUDE, PROGRAM, &cases, &coverage, &scope);
        assert_eq!(problems.iter().filter(|problem| problem.contains("re-execution differs")).count(), 2);
    });
}

#[test]
fn executes_binary_natural_arithmetic_in_the_prelude() {
    on_large_stack(|| {
        let registry = native_registry(PRELUDE, &slice_native_program(PROGRAM, &[])).unwrap();
        let n = |number: u64| Node::List(vec![leaf("mt-v"), binary_natural(number)]);
        let run = |operation: &str, left: u64, right: u64| {
            let term = Node::List(vec![leaf(operation), n(left), n(right)]);
            compact_native(&registry.reduce_result(META_THEORY_NATIVE_PROGRAM, &term, 10_000).unwrap().term)
        };
        let natural = |number: u64| {
            Node::List(vec![leaf("mt-v"), Node::List(vec![leaf("mt-natural"), Node::Leaf(number.to_string())])])
        };
        assert_eq!(run("mt-add", 1343, 999), natural(2342));
        assert_eq!(run("mt-sub", 1343, 999), natural(344));
        assert_eq!(run("mt-sub", 3, 9), Node::List(vec![leaf("mt-v"), leaf("mt-zero")]));
        assert_eq!(run("mt-mul", 121, 11), natural(1331));
        assert_eq!(run("mt-div", 1343, 10), natural(134));
        assert_eq!(run("mt-less", 4, 8), Node::List(vec![leaf("mt-v"), leaf("mt-true")]));
        assert_eq!(natural_value(&binary_natural(999_999)), Some(999_999));
        assert_eq!(natural_value(&Node::List(vec![leaf("mt-b0"), leaf("mt-zero")])), None);
        assert_eq!(expand_native(&compact_native(&binary_natural(1343))), binary_natural(1343));
    });
}
